// The engine's own version, and the check a generated twin makes against it.
//
// A twin is generated by the trax tool from the engine compiled into it, but at run time it imports whichever
// @traxsharp/state-machine the consumer installed. The two release together at one version, so a twin records
// the version it was generated for and refuses to load beside any other: an engine that reads the IR
// differently would otherwise run the twin without a word.

// Replaced with the package's version when the engine is built (tsup.config.ts) or bundled into the trax tool
// (tools/bundle-cli.mjs). Run from source it is not defined.
declare const __TRAX_ENGINE_VERSION__: string | undefined;

/** This engine's version: the npm package's, or `0.0.0` when it runs from source rather than a release. */
export const engineVersion: string =
  typeof __TRAX_ENGINE_VERSION__ === 'string' ? __TRAX_ENGINE_VERSION__ : '0.0.0';

// 0.0.0, with or without a prerelease tag, is a build from source: the placeholder in git.
const isRelease = (version: string): boolean => !/^0\.0\.0(?:[-+]|$)/.test(version);

/**
 * Throws unless this engine is the version a twin was generated for. A generated twin calls it when it is
 * imported, so a mismatch fails on load with what to do, rather than later in a transition. A build from
 * source on either side is not checked.
 */
export function requireEngineVersion(generatedFor: string): void {
  if (!isRelease(generatedFor) || !isRelease(engineVersion) || generatedFor === engineVersion) return;
  throw new Error(
    `This state-machine twin was generated by trax ${generatedFor} for @traxsharp/state-machine ` +
      `${generatedFor}, but @traxsharp/state-machine ${engineVersion} is installed. Install ` +
      `@traxsharp/state-machine@${generatedFor}, or regenerate the twin with trax ${engineVersion} ` +
      `(trax machine generate).`,
  );
}
